float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) {
        v += a * noise(p);
        p *= 2.0;
        a *= 0.5;
    }
    return v;
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    uv.y += 0.28;

    float t = iTime;
    float flick = fbm(vec2(t * 1.7, 0.0));
    vec2 p = uv;
    p.x -= 0.03 * sin(t * 5.0 + flick * 6.0);
    p.y -= flick * 0.04;

    float taper = clamp(1.0 - p.y * 1.4, 0.0, 1.0);
    float width = 0.16 * taper * taper + 0.015;
    float wobble = 0.05 * sin(p.y * 9.0 + t * 6.0) * taper;
    float d = abs(p.x + wobble) - width;
    d = max(d, p.y - 0.55);
    d = max(d, -p.y - 0.05);

    float glow = exp(-max(d, 0.0) * 18.0);
    float core = exp(-abs(d) * 45.0);

    vec3 flameCol = palette(clamp(p.y + 0.35, 0.0, 1.0),
                             vec3(0.55, 0.3, 0.1),
                             vec3(0.45, 0.3, 0.2),
                             vec3(1.0, 0.7, 0.4),
                             vec3(0.0, 0.1, 0.2));

    vec3 col = flameCol * glow;
    col += vec3(1.0, 0.9, 0.6) * core * 0.6;

    float vign = clamp(1.0 - length(uv) * 0.6, 0.0, 1.0);
    col += vec3(0.015, 0.01, 0.02) * vign;

    col = clamp(col, 0.0, 1.0);
    fragColor = vec4(col, 1.0);
}

