    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) {
        v += a * noise(p);
        p *= 2.0;
        a *= 0.5;
    }
    return v;
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec3 ro = vec3(0.0, -0.1, -1.6);
    vec3 rd = normalize(vec3(uv, 1.3));

    vec3 col = vec3(0.0);
    float t = 0.0;
    float dt = 0.045;

    for (int i = 0; i < 40; i++) {
        vec3 pos = ro + rd * t;
        float height = pos.y + 0.35;
        float radius = length(pos.xz);
        float taper = clamp(1.0 - height * 1.3, 0.0, 1.0);
        float shapeD = radius - (0.16 * taper * taper + 0.01);
        float n = fbm(pos.xy * 3.0 + vec2(1.3 * pos.z, -iTime * 1.6));
        float band = step(-0.4, height) * step(height, 0.55);
        float density = smoothstep(0.06, -0.06, shapeD) * clamp(taper * 1.2 + n * 0.4 - 0.15, 0.0, 1.0) * band;

        vec3 c = palette(clamp(height + 0.3, 0.0, 1.0),
                          vec3(0.5, 0.25, 0.1),
                          vec3(0.5, 0.3, 0.2),
                          vec3(1.0, 0.6, 0.3),
                          vec3(0.0, 0.05, 0.12));

        col += c * density * 0.09;
        t += dt;
    }

    col = clamp(col, 0.0, 1.0);
    fragColor = vec4(col, 1.0);
}

