void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec2 p = uv;
    p.y += 0.32;

    vec2 warp1 = vec2(
        fbm(p * 3.0 + vec2(0.0, iTime * 1.3)),
        fbm(p * 3.0 + vec2(5.2, -iTime * 1.1))
    );
    vec2 warp2 = vec2(
        fbm(p * 4.0 + 3.5 * warp1 + vec2(1.7, iTime * 0.9)),
        fbm(p * 4.0 + 3.5 * warp1 + vec2(8.3, -iTime * 0.9))
    );
    float n = fbm(p * 2.2 + 3.0 * warp2);

    float taper = clamp(1.0 - p.y * 1.3, 0.0, 1.0);
    float shape = smoothstep(0.34 * taper + 0.02, 0.0, abs(p.x + (warp2.x - 0.5) * 0.08 * taper));
    shape *= smoothstep(-0.08, 0.1, p.y);
    shape *= smoothstep(0.6, 0.1, p.y);

    vec3 col = palette(n, vec3(0.5, 0.2, 0.1), vec3(0.5, 0.3, 0.2), vec3(1.0, 0.8, 0.4), vec3(0.0, 0.1, 0.2));
    col *= shape * (0.5 + 0.6 * n);

    col = clamp(col, 0.0, 1.0);
    fragColor = vec4(col, 1.0);
}

