void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    uv.y += 0.22;

    float r = length(uv);
    float a = atan(uv.x, uv.y + 0.0001);

    float petal = pow(clamp(cos(a * 0.5), 0.0, 1.0), 3.0);
    float flick = fbm(vec2(a * 2.5 + 10.0, iTime * 2.2));
    float rad = petal * (0.32 + 0.05 * sin(iTime * 5.0 + a * 4.0)) + 0.015;
    rad *= (0.8 + 0.35 * flick);

    float d = r - rad;
    float glow = exp(-max(d, 0.0) * 14.0);
    float core = exp(-abs(d) * 32.0);

    vec3 col = palette(clamp(r * 2.2, 0.0, 1.0),
                        vec3(0.6, 0.3, 0.1),
                        vec3(0.4, 0.3, 0.2),
                        vec3(1.0, 0.7, 0.3),
                        vec3(0.0, 0.15, 0.2)) * glow;
    col += vec3(1.0, 0.95, 0.7) * core * 0.5;

    col = clamp(col, 0.0, 1.0);
    fragColor = vec4(col, 1.0);
}

