void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    uv.y += 0.3;

    float mask = smoothstep(0.4, 0.0, abs(uv.x) * (1.0 + max(uv.y, 0.0) * 1.6));
    mask *= smoothstep(-0.06, 0.14, uv.y);
    mask *= smoothstep(0.55, 0.15, uv.y);

    vec3 col = vec3(0.0);
    for (int i = 0; i < 4; i++) {
        float fi = float(i);
        vec2 q = uv * (2.0 + fi) + vec2(0.0, -iTime * (1.0 + fi * 0.4));
        float n = fbm(q);
        float layerMask = mask * (1.0 - fi * 0.18);
        vec3 c = palette(clamp(n * 0.5 + 0.5 - fi * 0.15, 0.0, 1.0),
                          vec3(0.5, 0.25, 0.1),
                          vec3(0.5, 0.3, 0.2),
                          vec3(1.0, 0.7, 0.4),
                          vec3(0.0, 0.05 + 0.04 * fi, 0.2));
        col += c * n * layerMask * 0.45;
    }

    col = clamp(col, 0.0, 1.0);
    fragColor = vec4(col, 1.0);
}

