float flameField(vec2 p, float t) {
    float taper = clamp(1.0 - p.y * 1.4, 0.0, 1.0);
    float flick = fbm(vec2(t * 3.0, p.y * 2.0 + 7.0));
    float width = 0.15 * taper * taper + 0.015 + 0.05 * flick * taper;
    float d = abs(p.x) - width;
    d = max(d, p.y - 0.5);
    d = max(d, -p.y - 0.05);
    return exp(-max(d, 0.0) * 25.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    uv.y += 0.25;

    vec3 col = vec3(0.0);
    for (int i = 0; i < 8; i++) {
        float fi = float(i);
        float w = exp(-fi * 0.4);
        float tOff = iTime - fi * 0.03;
        vec2 p = uv;
        p.y -= fi * 0.012;
        p.x += 0.01 * sin(fi * 2.1 + iTime);
        float f = flameField(p, tOff);
        vec3 c = palette(clamp(p.y + 0.3, 0.0, 1.0),
                          vec3(0.6, 0.3, 0.1),
                          vec3(0.4, 0.3, 0.2),
                          vec3(1.0, 0.7, 0.3),
                          vec3(0.0, 0.1, 0.2));
        col += c * f * w * 0.35;
    }

    col = clamp(col, 0.0, 1.0);
    fragColor = vec4(col, 1.0);
}

