void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    uv.y += 0.30;

    vec2 p = uv;
    float flick = fbm(vec2(p.y * 2.0 + 4.0, iTime * 2.3));
    p.x -= 0.05 * sin(iTime * 4.0 + p.y * 5.0) * clamp(p.y, 0.0, 1.0);

    float totalH = 0.62 + 0.06 * flick;
    float u = clamp(p.y / totalH, 0.0, 1.0);

    float belly = smoothstep(0.0, 0.22, u) * (1.0 - smoothstep(0.22, 1.0, u));
    float width = mix(0.045, 0.22, belly) * pow(1.0 - u, 1.1);
    width *= (0.8 + 0.35 * flick);
    width = max(width, 0.006);

    float d = abs(p.x) - width;
    d = max(d, p.y - totalH);
    d = max(d, -p.y - 0.04);

    float glow = exp(-max(d, 0.0) * 16.0);
    float core = exp(-abs(d) * 42.0);

    vec3 flameCol = palette(u,
                        vec3(0.6, 0.25, 0.05),
                        vec3(0.4, 0.3, 0.2),
                        vec3(1.0, 0.7, 0.35),
                        vec3(0.0, 0.12, 0.22));

    vec3 col = flameCol * glow;
    col += vec3(1.0, 0.95, 0.7) * core * 0.55;

    float wick = max(abs(p.x) - 0.014, abs(p.y + 0.06) - 0.07);
    float wickMask = smoothstep(0.012, -0.004, wick);
    col = mix(col, vec3(0.06, 0.05, 0.05), wickMask);

    float vign = clamp(1.0 - length(uv) * 0.55, 0.0, 1.0);
    col += vec3(0.01, 0.007, 0.015) * vign;

    col = clamp(col, 0.0, 1.0);
    fragColor = vec4(col, 1.0);
}

