    uv.y += 0.24;

    float r = length(uv);
    float a = atan(uv.x, uv.y + 0.0001);

    float flick = fbm(vec2(a * 2.0 + 8.0, iTime * 2.0));
    float tip = smoothstep(-0.05, 0.55, uv.y);
    float petal = pow(clamp(cos(a * 0.5), 0.0, 1.0), 1.6);
    float baseWidth = mix(0.34, 0.05, tip);
    float rad = petal * baseWidth * (0.85 + 0.3 * flick) + 0.012 * (1.0 - tip);

    float d = r - rad;
    d = max(d, uv.y - 0.62);
    float glow = exp(-max(d, 0.0) * 15.0);
    float core = exp(-abs(d) * 34.0);

    vec3 col = palette(clamp(uv.y * 1.6 + 0.4, 0.0, 1.0),
                        vec3(0.6, 0.3, 0.1),
                        vec3(0.4, 0.3, 0.2),
                        vec3(1.0, 0.7, 0.3),
                        vec3(0.0, 0.15, 0.2)) * glow;
    col += vec3(1.0, 0.95, 0.7) * core * 0.5;

    float wickD = max(abs(uv.x) - 0.012, abs(uv.y + 0.05) - 0.065);
    float wickMask = smoothstep(0.01, -0.005, wickD);
    col = mix(col, vec3(0.05, 0.05, 0.05), wickMask);

    col = clamp(col, 0.0, 1.0);
    fragColor = vec4(col, 1.0);
}

