void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    uv.y += 0.28;

    float t = iTime;
    float flickA = fbm(vec2(t * 1.8, 0.0));
    float flickB = fbm(vec2(t * 3.1 + 5.0, 1.0));
    float flickC = fbm(vec2(uv.y * 3.0 + t * 2.4, 2.0));

    vec2 p = uv;
    p.x -= (0.05 * sin(t * 5.0 + flickA * 7.0) + 0.03 * (flickB - 0.5));
    p.y -= 0.05 * (flickA - 0.5) + 0.02 * sin(t * 3.3);

    float heightVar = 1.3 + 0.35 * (flickB - 0.5) + 0.15 * sin(t * 4.1);
    float taper = clamp(1.0 - p.y * heightVar, 0.0, 1.0);
    float widthVar = 0.16 + 0.05 * (flickC - 0.5) + 0.02 * sin(t * 6.7 + p.y * 8.0);
    float width = widthVar * taper * taper + 0.015;
    float wobble = (0.06 + 0.03 * flickC) * sin(p.y * 9.0 + t * 6.0 + flickA * 4.0) * taper;
    float d = abs(p.x + wobble) - width;
    d = max(d, p.y - (0.5 + 0.08 * flickB));
    d = max(d, -p.y - 0.05);

    float glow = exp(-max(d, 0.0) * 18.0);
    float core = exp(-abs(d) * 45.0);

    vec3 flameCol = palette(clamp(p.y + 0.35, 0.0, 1.0),
                             vec3(0.55, 0.3, 0.1),
                             vec3(0.45, 0.3, 0.2),
                             vec3(1.0, 0.7, 0.4),
                             vec3(0.0, 0.1, 0.2));

    vec3 col = flameCol * glow;
    col += vec3(1.0, 0.9, 0.6) * core * 0.6;

    float wickD = max(abs(uv.x) - 0.013, abs(uv.y + 0.09) - 0.09);
    float wickMask = smoothstep(0.01, -0.005, wickD);
    col = mix(col, vec3(0.04, 0.04, 0.04), wickMask);
