float voronoi(vec2 p) {
    vec2 ip = floor(p);
    vec2 fp = fract(p);
    float minD = 1.5;
    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            vec2 cellOff = vec2(float(x), float(y));
            vec2 pt = cellOff + hash22(ip + cellOff);
