    vec2 p = uv;
    float lobe1 = length((p - vec2(0.02 * sin(t * 4.0 + n0 * 6.0), -0.05)) / vec2(0.14 + 0.05 * n0, 0.30 + 0.12 * n0)) - 1.0;
    float lobe2 = length((p - vec2(-0.03 * (n1 - 0.5) * 2.0, 0.05 + 0.05 * (n1 - 0.5))) / vec2(0.11 + 0.04 * n1, 0.22 + 0.1 * n1)) - 1.0;
    float lobe3 = length((p - vec2(0.02 * (n2 - 0.5) * 3.0, 0.18 + 0.08 * (n2 - 0.5))) / vec2(0.08 + 0.03 * n2, 0.14 + 0.08 * n2)) - 1.0;

    float d = smin(lobe1, lobe2, 0.3);
    d = smin(d, lobe3, 0.25);
    d = max(d, -p.y - 0.05);

    float glow = exp(-max(d, 0.0) * 10.0);
    float core = exp(-abs(d) * 30.0);

    float brightness = clamp(0.7 + 0.3 * n0 + 0.2 * n1, 0.3, 1.4);

    vec3 flameCol = palette(clamp(p.y + 0.35, 0.0, 1.0),
                             vec3(0.55, 0.3, 0.1),
                             vec3(0.45, 0.3, 0.2),
                             vec3(1.0, 0.7, 0.4),
                             vec3(0.0, 0.1, 0.2));

    vec3 col = flameCol * glow * brightness;
    col += vec3(1.0, 0.9, 0.6) * core * 0.6 * brightness;

    float wickD = max(abs(uv.x) - 0.013, abs(uv.y + 0.09) - 0.09);
    float wickMask = smoothstep(0.01, -0.005, wickD);
    col = mix(col, vec3(0.04, 0.04, 0.04), wickMask);

    float vign = clamp(1.0 - length(uv) * 0.6, 0.0, 1.0);
    col += vec3(0.015, 0.01, 0.02) * vign;

    col = clamp(col, 0.0, 1.0);
    fragColor = vec4(col, 1.0);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

float noise3(vec3 p) {
    float n1 = noise(p.xy + p.z * 1.7);
    float n2 = noise(p.yz + p.x * 1.3);
    float n3 = noise(p.zx + p.y * 2.1);
    return (n1 + n2 + n3) / 3.0;
}

float density(vec3 p, float t) {
    float h = clamp(p.y, 0.0, 1.0);
    float radius = mix(0.16, 0.02, h * h);
    vec3 q = p;
    q.xz *= 1.0 + 0.5 * h;
    float dist = length(q.xz);
    float shapeFalloff = smoothstep(radius, 0.0, dist);
    float heightFalloff = smoothstep(1.0, 0.0, p.y) * smoothstep(0.0, 0.05, p.y);
    vec3 flowP = p * 3.0 + vec3(0.0, -t * 1.8, 0.0);
    float turb = noise3(flowP);
    float d = shapeFalloff * heightFalloff * (0.4 + 0.8 * turb);
    return max(d, 0.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float t = iTime;

    vec3 ro = vec3(0.0, 0.35, -1.1);
    vec3 target = vec3(0.0, 0.35, 0.0);
    vec3 fwd = normalize(target - ro);
    vec3 right = normalize(cross(vec3(0.0, 1.0, 0.0), fwd));
    vec3 up = cross(fwd, right);
    vec3 rd = normalize(fwd * 1.4 + uv.x * right + uv.y * up);

    vec3 col = vec3(0.0);
    float trans = 1.0;
    float dt = 0.035;
    vec3 pos = ro;
    const int STEPS = 40;
    for (int i = 0; i < STEPS; i++) {
        pos += rd * dt;
        if (pos.y < -0.1 || pos.y > 1.3 || trans < 0.02) continue;
        float dens = density(pos, t);
        if (dens > 0.001) {
            float heightC = clamp(pos.y, 0.0, 1.0);
            vec3 flameCol = palette(heightC, vec3(0.55, 0.3, 0.1), vec3(0.45, 0.3, 0.2), vec3(1.0, 0.7, 0.4), vec3(0.0, 0.1, 0.2));
            float absorb = dens * dt * 6.0;
            col += trans * absorb * flameCol * 2.0;
            trans *= exp(-absorb);
        }
    }

    float wickD = length(uv - vec2(0.0, -0.28));
    col += vec3(1.0, 0.5, 0.15) * exp(-wickD * 40.0) * 0.3;

    float vign = clamp(1.0 - length(uv) * 0.5, 0.0, 1.0);
    col *= vign * 0.6 + 0.4;

    col = clamp(col, 0.0, 1.0);
    fragColor = vec4(col, 1.0);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float t = iTime;

    vec2 origin = vec2(0.0, -0.22);
    vec2 v = uv - origin;
    v += vec2(1e-4, 1e-4);
    float r = length(v);
    float theta = atan(v.y, v.x);

    float vertical = sin(theta);
    float angNoise = noise(vec2(theta * 2.5 + 10.0, t * 2.6));
    float angNoise2 = noise(vec2(theta * 5.0 - 3.0, t * 4.1 + 7.0));
    float flicker = 0.7 + 0.5 * angNoise + 0.25 * angNoise2;

    float shapeBase = smoothstep(-1.0, 1.0, vertical);
    float maxR = mix(0.035, 0.62, pow(shapeBase, 1.4)) * flicker;

    float edge = smoothstep(maxR, maxR - 0.09, r);
    float coreEdge = smoothstep(maxR * 0.5, maxR * 0.5 - 0.05, r);

    float heightN = clamp((uv.y - origin.y) / 0.6, 0.0, 1.0);
    vec3 flameCol = palette(heightN,
                             vec3(0.55, 0.3, 0.1),
                             vec3(0.45, 0.3, 0.2),
                             vec3(1.0, 0.7, 0.4),
                             vec3(0.0, 0.1, 0.2));

    vec3 col = flameCol * edge * 0.9;
    col += vec3(1.0, 0.9, 0.55) * coreEdge * 0.6;

    float wickD = max(abs(uv.x) - 0.012, abs(uv.y - origin.y + 0.06) - 0.06);
    float wickMask = smoothstep(0.008, -0.004, wickD);
    col = mix(col, vec3(0.05, 0.045, 0.04), wickMask);

    const int NUM_EMBERS = 10;
    for (int i = 0; i < NUM_EMBERS; i++) {
        float fi = float(i);
        float seed = fi * 17.13;
        float life = fract(t * 0.25 + hash21(vec2(seed, 1.0)));
        float ex = (hash21(vec2(seed, 2.0)) - 0.5) * 0.25 * (0.3 + life);
        float ey = origin.y + life * 0.9;
        float drift = sin(t * 2.0 + seed) * 0.03 * life;
        vec2 epos = vec2(ex + drift, ey);
        float ed = length(uv - epos);
        float emberGlow = exp(-ed * 90.0) * (1.0 - life) * 0.5;
        col += vec3(1.0, 0.45, 0.1) * emberGlow;
    }

    float vign = clamp(1.0 - length(uv) * 0.55, 0.0, 1.0);
    col += vec3(0.012, 0.008, 0.02) * vign;

    col = clamp(col, 0.0, 1.0);
    fragColor = vec4(col, 1.0);
}
